import { useState } from 'react';
import { Icon, tones } from '../components/ui.jsx';

/** Keeps original conversion assumptions; operator count is informational, not a multiplier. */
export function calculateImpact(plastic, factors) {
  return {
    boards: Math.round(plastic / factors.plasticKgPerBoard),
    co2: Math.round(plastic * factors.avoidedCo2KgPerPlasticKg),
    revenue: Math.round(plastic * factors.revenuePhpPerPlasticKg),
  };
}

/** Connects accessible range controls to live community-impact estimates. */
export function CalculatorSection({ section, locale }) {
  const [values, setValues] = useState(() => Object.fromEntries(section.inputs.map(input => [input.id, input.defaultValue])));
  const result = calculateImpact(values.plastic, section.conversionFactors);
  return <section id={section.id} className="py-20 bg-gradient-to-br from-brand-dark to-slate-900 text-white overflow-hidden"><div className="section-container calculator-grid grid gap-12 items-center">
    <div className="space-y-4"><p className="text-xs font-bold text-brand-500 uppercase">{section.eyebrow}</p><h2 className="text-3xl sm:text-4xl font-extrabold">{section.title}</h2><p className="text-slate-300 text-sm leading-relaxed">{section.description}</p><p className="bg-brand-900/50 p-4 rounded-xl border border-brand-500/20 text-xs text-brand-200"><Icon name={section.note.icon} className="text-brand-500 mr-1" />{section.note.text}</p></div>
    <div className="bg-white/10 backdrop-blur-md p-8 rounded-3xl border border-white/15 shadow-2xl space-y-6">
      {section.inputs.map(input => <div key={input.id}>
        <div className="flex flex-wrap justify-between items-center gap-2 mb-2"><label htmlFor={`input-${input.id}`} className="text-sm font-semibold text-slate-200">{input.label}</label><output htmlFor={`input-${input.id}`} className={`text-xl font-bold ${tones[input.tone].highlight}`}>{values[input.id]} {input.unit}</output></div>
        <input type="range" id={`input-${input.id}`} min={input.min} max={input.max} step={input.step} value={values[input.id]} aria-valuetext={`${values[input.id]} ${input.unit}`} onChange={event => setValues({ ...values, [input.id]: Math.min(input.max, Math.max(input.min, Number(event.target.value))) })} className={`w-full cursor-pointer ${input.tone === 'pink' ? 'accent-pink-500' : 'accent-brand-500'}`} />
      </div>)}
      <div className="output-grid grid gap-4 pt-6 border-t border-white/10 text-center" aria-live="polite" aria-atomic="true">
        {section.outputs.map(output => <div key={output.id} className="bg-black/30 p-4 rounded-2xl border border-white/5"><Icon name={output.icon} className={`text-xl mb-1 ${tones[output.tone].highlight}`} /><span className="block text-xs text-slate-300">{output.label}</span><output className={`block text-2xl font-bold mt-1 ${output.id === 'boards' ? 'text-white' : tones[output.tone].highlight}`}>{output.symbol || ''}{result[output.id].toLocaleString(locale)}{output.unit ? ` ${output.unit}` : ''}</output></div>)}
      </div>
    </div>
  </div></section>;
}